.community-body { font-size: 16px; color: var(--gray); max-width: 640px; margin: 0 auto 36px; line-height: 1.8; font-family: 'Inter', sans-serif; text-transform: none; }

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
