@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --bg: #141414;
  --bg-2: #1a1a1a;
  --bg-3: #222222;
  --white: #FFFFFF;
  --gray: #999999;
  --gray-light: #cccccc;
  --border: #2a2a2a;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--white);
  font-family: 'Inter', Helvetica Neue, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5 {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

/* ─── TOP PROMO BAR ─── */
.promo-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.promo-bar a { text-decoration: underline; text-underline-offset: 3px; }
.promo-bar a:hover { opacity: 0.8; }

/* ─── NAVIGATION ─── */
.nav {
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}
.nav-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--white);
}
.nav-logo span { color: var(--red); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-light);
  transition: color 0.2s;
}
.nav-links a:hover,
.nav-links a.active { color: var(--red); }
.nav-utility {
  display: flex;
  align-items: center;
  gap: 12px;
}
.btn-nav {
  padding: 9px 20px;
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-block;
}
.btn-nav-outline {
  background: transparent;
  border: 1px solid var(--white);
  color: var(--white);
}
.btn-nav-outline:hover { background: var(--white); color: var(--bg); }
.btn-nav-red {
  background: var(--red);
  color: var(--white);
}
.btn-nav-red:hover { background: var(--red-dark); }

/* ─── BUTTONS ─── */
.btn {
  display: inline-block;
  padding: 16px 40px;
  font-family: 'Oswald', sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  border: none;
  transition: all 0.25s;
  text-align: center;
}
.btn-red { background: var(--red); color: var(--white); }
.btn-red:hover { background: var(--red-dark); transform: translateY(-1px); }
.btn-white { background: var(--white); color: var(--bg); }
.btn-white:hover { background: var(--gray-light); transform: translateY(-1px); }
.btn-outline-white {
  background: transparent;
  border: 2px solid var(--white);
  color: var(--white);
}
.btn-outline-white:hover { background: var(--white); color: var(--bg); }
.btn-outline-red {
  background: transparent;
  border: 2px solid var(--red);
  color: var(--red);
}
.btn-outline-red:hover { background: var(--red); color: var(--white); }
.btn-lg { padding: 20px 56px; font-size: 17px; }

/* ─── SECTIONS ─── */
.section { padding: 96px 24px; }
.section-sm { padding: 64px 24px; }
.container { max-width: 1200px; margin: 0 auto; }
.container-wide { max-width: 1400px; margin: 0 auto; }

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: var(--bg);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0000 0%, #141414 40%, #0a0a0a 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 60%, rgba(255,0,0,0.15) 0%, transparent 65%);
}
.hero-content { position: relative; z-index: 2; max-width: 900px; padding: 48px 24px; }
.hero-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
}
.hero-title {
  font-size: clamp(52px, 9vw, 100px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 24px;
  text-shadow: 0 4px 40px rgba(0,0,0,0.6);
}
.hero-title span { color: var(--red); }
.hero-subtitle {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--gray-light);
  max-width: 580px;
  margin: 0 auto 40px;
  line-height: 1.65;
  font-weight: 300;
  text-transform: none;
  font-family: 'Inter', sans-serif;
}
.hero-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── RED DIVIDER ─── */
.red-line { width: 60px; height: 4px; background: var(--red); margin-bottom: 24px; }
.red-line-center { margin-left: auto; margin-right: auto; }

/* ─── SECTION HEADING ─── */
.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.25em;
  color: var(--red);
  text-transform: uppercase;
  margin-bottom: 12px;
}
.section-title {
  font-size: clamp(36px, 5vw, 60px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 20px;
}
.section-body {
  font-size: 16px;
  color: var(--gray);
  max-width: 600px;
  line-height: 1.8;
  font-family: 'Inter', sans-serif;
  text-transform: none;
}

/* ─── TWO WAYS SECTION ─── */
.two-ways { display: grid; grid-template-columns: 1fr 1fr; }
.two-ways-card {
  padding: 80px 60px;
  position: relative;
  overflow: hidden;
}
.two-ways-card:first-child { background: var(--bg-2); }
.two-ways-card:last-child { background: #0d0d0d; }
.two-ways-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 4px; height: 100%;
  background: var(--red);
}
.two-ways-card:last-child::before { left: auto; right: 0; }
.two-ways-num {
  font-family: 'Oswald', sans-serif;
  font-size: 100px;
  font-weight: 700;
  color: rgba(255,0,0,0.08);
  position: absolute;
  top: 20px; right: 24px;
  line-height: 1;
}
.two-ways-icon { font-size: 40px; margin-bottom: 20px; }
.two-ways-title { font-size: 36px; font-weight: 700; color: var(--white); margin-bottom: 16px; }
.two-ways-body { font-size: 15px; color: var(--gray); line-height: 1.8; font-family: 'Inter', sans-serif; text-transform: none; max-width: 400px; }

/* ─── STUDIO EXPERIENCE ─── */
.studio-exp {
  background: linear-gradient(135deg, #1a0000 0%, #0d0000 100%);
  padding: 100px 24px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.studio-exp::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(255,0,0,0.2) 0%, transparent 70%);
}
.studio-exp > * { position: relative; z-index: 1; }

/* ─── FREE TRIAL ─── */
.free-trial {
  background: var(--red);
  padding: 96px 24px;
  text-align: center;
}
.free-trial-title {
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 36px;
}

/* ─── CAROUSEL ─── */
.carousel-section { background: var(--bg-2); padding: 80px 0; }
.carousel-wrap { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.carousel-slide {
  min-width: 33.333%;
  padding: 0 8px;
  flex-shrink: 0;
}
.carousel-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: 2px;
}
.carousel-placeholder {
  width: 100%;
  aspect-ratio: 4/3;
  background: var(--bg-3);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 2px;
  position: relative;
  overflow: hidden;
}
.carousel-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0000, #141414);
}
.carousel-placeholder-text {
  position: relative;
  font-family: 'Oswald', sans-serif;
  font-size: 24px;
  font-weight: 700;
  color: rgba(255,0,0,0.4);
  letter-spacing: 0.1em;
  text-align: center;
}
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
  padding: 0 24px;
}
.carousel-btn {
  width: 48px; height: 48px;
  background: transparent;
  border: 2px solid var(--border);
  color: var(--white);
  font-size: 20px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.carousel-btn:hover { border-color: var(--red); color: var(--red); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px;
  background: var(--border);
  border-radius: 50%;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* ─── NEWSLETTER ─── */
.newsletter {
  background: var(--bg-2);
  padding: 80px 24px;
  text-align: center;
  border-top: 1px solid var(--border);
}
.newsletter-form {
  display: flex;
  max-width: 480px;
  margin: 28px auto 0;
  gap: 0;
}
.newsletter-input {
  flex: 1;
  padding: 16px 20px;
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-right: none;
  color: var(--white);
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-input:focus { border-color: var(--red); }
.newsletter-input::placeholder { color: var(--gray); }
.newsletter-input.error { border-color: #ff4444; }
.newsletter-btn {
  padding: 16px 28px;
  background: var(--red);
  color: var(--white);
  border: none;
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.2s;
}
.newsletter-btn:hover { background: var(--red-dark); }
.newsletter-msg { margin-top: 12px; font-size: 13px; min-height: 20px; }
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: #ff4444; }

/* ─── FOOTER ─── */
.footer {
  background: #0d0d0d;
  border-top: 1px solid var(--border);
  padding: 64px 24px 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  max-width: 1200px;
  margin: 0 auto 48px;
}
.footer-brand-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.footer-brand-logo span { color: var(--red); }
.footer-tagline { font-size: 13px; color: var(--gray); line-height: 1.7; max-width: 260px; text-transform: none; }
.footer-col-title {
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 10px; }
.footer-links a {
  font-size: 13px;
  color: var(--gray);
  transition: color 0.2s;
  text-transform: none;
}
.footer-links a:hover { color: var(--red); }
.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 32px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-copy { font-size: 12px; color: var(--gray); text-transform: none; }
.country-select {
  background: var(--bg-3);
  border: 1px solid var(--border);
  color: var(--gray-light);
  padding: 8px 16px;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  cursor: pointer;
  outline: none;
}
.country-select:focus { border-color: var(--red); }

/* ─── PAGE HERO (interior) ─── */
.page-hero {
  background: linear-gradient(135deg, #1a0000 0%, #141414 50%, #0a0a0a 100%);
  padding: 100px 24px 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 100%, rgba(255,0,0,0.12) 0%, transparent 60%);
}
.page-hero > * { position: relative; z-index: 1; }
.page-hero-title { font-size: clamp(48px, 7vw, 84px); font-weight: 700; color: var(--white); }
.page-hero-sub { font-size: 16px; color: var(--gray); margin-top: 16px; max-width: 540px; margin-left: auto; margin-right: auto; font-family: 'Inter', sans-serif; text-transform: none; line-height: 1.7; }

/* ─── METHOD OVERVIEW ─── */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.method-img-placeholder {
  aspect-ratio: 5/4;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.method-img-placeholder::before {
  content: 'REDROOM';
  font-family: 'Oswald', sans-serif;
  font-size: 48px;
  font-weight: 700;
  color: rgba(255,0,0,0.15);
  letter-spacing: 0.15em;
}

/* ─── SCHEDULE TABLE ─── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 40px;
}
.schedule-table th {
  background: var(--red);
  color: var(--white);
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 16px 24px;
  text-align: left;
}
.schedule-table td {
  padding: 18px 24px;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--gray-light);
}
.schedule-table tr:hover td { background: var(--bg-2); color: var(--white); }
.schedule-table .day-cell {
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  font-size: 16px;
  color: var(--white);
  letter-spacing: 0.06em;
}

/* ─── TOGGLE ─── */
.toggle-wrap { margin: 48px 0; }
.toggle-tabs {
  display: flex;
  border: 1px solid var(--border);
  max-width: 400px;
  margin: 0 auto 48px;
}
.toggle-tab {
  flex: 1;
  padding: 16px 24px;
  background: transparent;
  border: none;
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.25s;
  position: relative;
}
.toggle-tab.active {
  background: var(--red);
  color: var(--white);
}
.toggle-tab:not(.active):hover { color: var(--white); background: rgba(255,255,255,0.05); }
.toggle-panel { display: none; }
.toggle-panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  animation: fadeIn 0.35s ease;
}
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.toggle-panel-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.toggle-panel-img-label {
  font-family: 'Oswald', sans-serif;
  font-size: 36px;
  font-weight: 700;
  color: rgba(255,0,0,0.25);
  letter-spacing: 0.12em;
}
.toggle-panel-content .section-title { font-size: 42px; }

/* ─── INSTRUCTOR GRID ─── */
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 22px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s;
}
.filter-btn:hover { border-color: var(--white); color: var(--white); }
.filter-btn.active { background: var(--red); border-color: var(--red); color: var(--white); }
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg-2);
  border: 1px solid var(--border);
  padding: 0;
  overflow: hidden;
  transition: transform 0.25s, border-color 0.25s;
}
.instructor-card:hover { transform: translateY(-4px); border-color: var(--red); }
.instructor-avatar {
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: flex-end;
  padding: 24px;
  position: relative;
  overflow: hidden;
}
.instructor-avatar::before {
  content: attr(data-initial);
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-family: 'Oswald', sans-serif;
  font-size: 72px;
  font-weight: 700;
  color: rgba(255,0,0,0.18);
}
.instructor-info { padding: 20px; }
.instructor-name {
  font-family: 'Oswald', sans-serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 4px;
  letter-spacing: 0.05em;
}
.instructor-location { font-size: 12px; color: var(--red); text-transform: uppercase; letter-spacing: 0.15em; margin-bottom: 16px; }
.instructor-book {
  display: block;
  padding: 10px 0;
  text-align: center;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: all 0.2s;
}
.instructor-book:hover { background: var(--red); border-color: var(--red); color: var(--white); }
.instructor-card.hidden { display: none; }

/* ─── FAQ ACCORDION ─── */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border);
  overflow: hidden;
}
.faq-question {
  width: 100%;
  background: transparent;
  border: none;
  text-align: left;
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  gap: 16px;
  color: var(--white);
}
.faq-question-text {
  font-family: 'Oswald', sans-serif;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.faq-icon {
  width: 28px; height: 28px;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--red);
  font-size: 18px;
  font-weight: 300;
  transition: transform 0.3s, background 0.2s;
}
.faq-item.open .faq-icon { background: var(--red); color: var(--white); transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  padding: 0;
}
.faq-item.open .faq-answer { max-height: 300px; padding-bottom: 24px; }
.faq-answer-text { font-size: 15px; color: var(--gray); line-height: 1.8; text-transform: none; font-family: 'Inter', sans-serif; }

/* ─── DIGITAL FEATURES ─── */
.features-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
}
.feature-card {
  background: var(--bg-2);
  padding: 48px 40px;
  position: relative;
  overflow: hidden;
  border-left: 4px solid transparent;
  transition: border-color 0.25s, background 0.25s;
}
.feature-card:hover { border-left-color: var(--red); background: var(--bg-3); }
.feature-num {
  font-family: 'Oswald', sans-serif;
  font-size: 80px;
  font-weight: 700;
  color: rgba(255,0,0,0.06);
  position: absolute;
  top: 16px; right: 24px;
  line-height: 1;
}
.feature-icon { font-size: 32px; margin-bottom: 16px; }
.feature-title {
  font-family: 'Oswald', sans-serif;
  font-size: 26px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.feature-body { font-size: 14px; color: var(--gray); line-height: 1.8; text-transform: none; font-family: 'Inter', sans-serif; max-width: 380px; }

/* ─── CTA BAND ─── */
.cta-band {
  background: var(--bg-2);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 64px 24px;
  text-align: center;
}
.cta-band-title {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}
.cta-band-sub { font-size: 15px; color: var(--gray); margin-bottom: 32px; font-family: 'Inter', sans-serif; text-transform: none; }
.cta-band-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── COMMUNITY PROMO ─── */
.community-promo {
  padding: 96px 24px;
  text-align: center;
  background: var(--bg);
}
.community-title { font-size: clamp(40px, 5vw, 64px); font-weight: 700; color: var(--white); margin-bottom: 24px; }
.community-body { font-size: 16px; color: var(--gray); max-width: 640px; margin: 0 auto 36px; line-height: 1.8; font-family: 'Inter', sans-serif; text-transform: none; }

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .two-ways { grid-template-columns: 1fr; }
  .two-ways-card::before { width: 100%; height: 4px; top: 0; left: 0; }
  .two-ways-card:last-child::before { top: auto; bottom: 0; right: auto; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-utility .btn-nav-outline { display: none; }
  .instructor-grid { grid-template-columns: repeat(2, 1fr); }
  .method-grid { grid-template-columns: 1fr; }
  .toggle-panel.active { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .two-ways-card { padding: 48px 32px; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { border-right: 1px solid var(--border); border-bottom: none; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .carousel-slide { min-width: 100%; }
  .hero-btns { flex-direction: column; align-items: center; }
}

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --bg: #141414;
  --bg-2: #1a1a1a;
  --bg-3: #222222;
  --white: #FFFFFF;
  --gray: #999999;
  --gray-light: #cccccc;
  --border: #2a2a2a;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--white);
  font-family: 'Inter', Helvetica Neue, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5 {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

/* ─── TOP PROMO BAR ─── */
.promo-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.promo-bar a { text-decoration: underline; text-underline-offset: 3px; }
.promo-bar a:hover { opacity: 0.8; }

/* ─── NAVIGATION ─── */
.nav {
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}
.nav-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--white);
}
.nav-logo span { color: var(--red); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-light);
  transition: color 0.2s;
}
.nav-links a:hover,
.nav-links a.active { color: var(--red); }
.nav-utility {
  display: flex;
  align-items: center;
  gap: 12px;
}
.btn-nav {
  padding: 9px 20px;
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-block;
}
.btn-nav-outline {
  background: transparent;
  border: 1px solid var(--white);
  color: var(--white);
}
.btn-nav-outline:hover { background: var(--white); color: var(--bg); }
.btn-nav-red {
  background: var(--red);
  color: var(--white);
}
.btn-nav-red:hover { background: var(--red-dark); }

/* ─── BUTTONS ─── */
.btn {
  display: inline-block;
  padding: 16px 40px;
  font-family: 'Oswald', sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  border: none;
  transition: all 0.25s;
  text-align: center;
}
.btn-red { background: var(--red); color: var(--white); }
.btn-red:hover { background: var(--red-dark); transform: translateY(-1px); }
.btn-white { background: var(--white); color: var(--bg); }
.btn-white:hover { background: var(--gray-light); transform: translateY(-1px); }
.btn-outline-white {
  background: transparent;
  border: 2px solid var(--white);
  color: var(--white);
}
.btn-outline-white:hover { background: var(--white); color: var(--bg); }
.btn-outline-red {
  background: transparent;
  border: 2px solid var(--red);
  color: var(--red);
}
.btn-outline-red:hover { background: var(--red); color: var(--white); }
.btn-lg { padding: 20px 56px; font-size: 17px; }

/* ─── SECTIONS ─── */
.section { padding: 96px 24px; }
.section-sm { padding: 64px 24px; }
.container { max-width: 1200px; margin: 0 auto; }
.container-wide { max-width: 1400px; margin: 0 auto; }

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: var(--bg);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0000 0%, #141414 40%, #0a0a0a 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 60%, rgba(255,0,0,0.15) 0%, transparent 65%);
}
.hero-content { position: relative; z-index: 2; max-width: 900px; padding: 48px 24px; }
.hero-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
}
.hero-title {
  font-size: clamp(52px, 9vw, 100px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 24px;
  text-shadow: 0 4px 40px rgba(0,0,0,0.6);
}
.hero-title span { color: var(--red); }
.hero-subtitle {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--gray-light);
  max-width: 580px;
  margin: 0 auto 40px;
  line-height: 1.65;
  font-weight: 300;
  text-transform: none;
  font-family: 'Inter', sans-serif;
}
.hero-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── RED DIVIDER ─── */
.red-line { width: 60px; height: 4px; background: var(--red); margin-bottom: 24px; }
.red-line-center { margin-left: auto; margin-right: auto; }

/* ─── SECTION HEADING ─── */
.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.25em;
  color: var(--red);
  text-transform: uppercase;
  margin-bottom: 12px;
}
.section-title {
  font-size: clamp(36px, 5vw, 60px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 20px;
}
.section-body {
  font-size: 16px;
  color: var(--gray);
  max-width: 600px;
  line-height: 1.8;
  font-family: 'Inter', sans-serif;
  text-transform: none;
}

/* ─── TWO WAYS SECTION ─── */
.two-ways { display: grid; grid-template-columns: 1fr 1fr; }
.two-ways-card {
  padding: 80px 60px;
  position: relative;
  overflow: hidden;
}
.two-ways-card:first-child { background: var(--bg-2); }
.two-ways-card:last-child { background: #0d0d0d; }
.two-ways-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 4px; height: 100%;
  background: var(--red);
}
.two-ways-card:last-child::before { left: auto; right: 0; }
.two-ways-num {
  font-family: 'Oswald', sans-serif;
  font-size: 100px;
  font-weight: 700;
  color: rgba(255,0,0,0.08);
  position: absolute;
  top: 20px; right: 24px;
  line-height: 1;
}
.two-ways-icon { font-size: 40px; margin-bottom: 20px; }
.two-ways-title { font-size: 36px; font-weight: 700; color: var(--white); margin-bottom: 16px; }
.two-ways-body { font-size: 15px; color: var(--gray); line-height: 1.8; font-family: 'Inter', sans-serif; text-transform: none; max-width: 400px; }

/* ─── STUDIO EXPERIENCE ─── */
.studio-exp {
  background: linear-gradient(135deg, #1a0000 0%, #0d0000 100%);
  padding: 100px 24px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.studio-exp::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(255,0,0,0.2) 0%, transparent 70%);
}
.studio-exp > * { position: relative; z-index: 1; }

/* ─── FREE TRIAL ─── */
.free-trial {
  background: var(--red);
  padding: 96px 24px;
  text-align: center;
}
.free-trial-title {
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 36px;
}

/* ─── CAROUSEL ─── */
.carousel-section { background: var(--bg-2); padding: 80px 0; }
.carousel-wrap { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.carousel-slide {
  min-width: 33.333%;
  padding: 0 8px;
  flex-shrink: 0;
}
.carousel-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: 2px;
}
.carousel-placeholder {
  width: 100%;
  aspect-ratio: 4/3;
  background: var(--bg-3);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 2px;
  position: relative;
  overflow: hidden;
}
.carousel-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0000, #141414);
}
.carousel-placeholder-text {
  position: relative;
  font-family: 'Oswald', sans-serif;
  font-size: 24px;
  font-weight: 700;
  color: rgba(255,0,0,0.4);
  letter-spacing: 0.1em;
  text-align: center;
}
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
  padding: 0 24px;
}
.carousel-btn {
  width: 48px; height: 48px;
  background: transparent;
  border: 2px solid var(--border);
  color: var(--white);
  font-size: 20px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.carousel-btn:hover { border-color: var(--red); color: var(--red); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px;
  background: var(--border);
  border-radius: 50%;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* ─── NEWSLETTER ─── */
.newsletter {
  background: var(--bg-2);
  padding: 80px 24px;
  text-align: center;
  border-top: 1px solid var(--border);
}
.newsletter-form {
  display: flex;
  max-width: 480px;
  margin: 28px auto 0;
  gap: 0;
}
.newsletter-input {
  flex: 1;
  padding: 16px 20px;
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-right: none;
  color: var(--white);
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-input:focus { border-color: var(--red); }
.newsletter-input::placeholder { color: var(--gray); }
.newsletter-input.error { border-color: #ff4444; }
.newsletter-btn {
  padding: 16px 28px;
  background: var(--red);
  color: var(--white);
  border: none;
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.2s;
}
.newsletter-btn:hover { background: var(--red-dark); }
.newsletter-msg { margin-top: 12px; font-size: 13px; min-height: 20px; }
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: #ff4444; }

/* ─── FOOTER ─── */
.footer {
  background: #0d0d0d;
  border-top: 1px solid var(--border);
  padding: 64px 24px 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  max-width: 1200px;
  margin: 0 auto 48px;
}
.footer-brand-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.footer-brand-logo span { color: var(--red); }
.footer-tagline { font-size: 13px; color: var(--gray); line-height: 1.7; max-width: 260px; text-transform: none; }
.footer-col-title {
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 10px; }
.footer-links a {
  font-size: 13px;
  color: var(--gray);
  transition: color 0.2s;
  text-transform: none;
}
.footer-links a:hover { color: var(--red); }
.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 32px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-copy { font-size: 12px; color: var(--gray); text-transform: none; }
.country-select {
  background: var(--bg-3);
  border: 1px solid var(--border);
  color: var(--gray-light);
  padding: 8px 16px;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  cursor: pointer;
  outline: none;
}
.country-select:focus { border-color: var(--red); }

/* ─── PAGE HERO (interior) ─── */
.page-hero {
  background: linear-gradient(135deg, #1a0000 0%, #141414 50%, #0a0a0a 100%);
  padding: 100px 24px 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 100%, rgba(255,0,0,0.12) 0%, transparent 60%);
}
.page-hero > * { position: relative; z-index: 1; }
.page-hero-title { font-size: clamp(48px, 7vw, 84px); font-weight: 700; color: var(--white); }
.page-hero-sub { font-size: 16px; color: var(--gray); margin-top: 16px; max-width: 540px; margin-left: auto; margin-right: auto; font-family: 'Inter', sans-serif; text-transform: none; line-height: 1.7; }

/* ─── METHOD OVERVIEW ─── */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.method-img-placeholder {
  aspect-ratio: 5/4;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.method-img-placeholder::before {
  content: 'REDROOM';
  font-family: 'Oswald', sans-serif;
  font-size: 48px;
  font-weight: 700;
  color: rgba(255,0,0,0.15);
  letter-spacing: 0.15em;
}

/* ─── SCHEDULE TABLE ─── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 40px;
}
.schedule-table th {
  background: var(--red);
  color: var(--white);
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 16px 24px;
  text-align: left;
}
.schedule-table td {
  padding: 18px 24px;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--gray-light);
}
.schedule-table tr:hover td { background: var(--bg-2); color: var(--white); }
.schedule-table .day-cell {
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  font-size: 16px;
  color: var(--white);
  letter-spacing: 0.06em;
}

/* ─── TOGGLE ─── */
.toggle-wrap { margin: 48px 0; }
.toggle-tabs {
  display: flex;
  border: 1px solid var(--border);
  max-width: 400px;
  margin: 0 auto 48px;
}
.toggle-tab {
  flex: 1;
  padding: 16px 24px;
  background: transparent;
  border: none;
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.25s;
  position: relative;
}
.toggle-tab.active {
  background: var(--red);
  color: var(--white);
}
.toggle-tab:not(.active):hover { color: var(--white); background: rgba(255,255,255,0.05); }
.toggle-panel { display: none; }
.toggle-panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  animation: fadeIn 0.35s ease;
}
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.toggle-panel-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.toggle-panel-img-label {
  font-family: 'Oswald', sans-serif;
  font-size: 36px;
  font-weight: 700;
  color: rgba(255,0,0,0.25);
  letter-spacing: 0.12em;
}
.toggle-panel-content .section-title { font-size: 42px; }

/* ─── INSTRUCTOR GRID ─── */
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 22px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s;
}
.filter-btn:hover { border-color: var(--white); color: var(--white); }
.filter-btn.active { background: var(--red); border-color: var(--red); color: var(--white); }
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg-2);
  border: 1px solid var(--border);
  padding: 0;
  overflow: hidden;
  transition: transform 0.25s, border-color 0.25s;
}
.instructor-card:hover { transform: translateY(-4px); border-color: var(--red); }
.instructor-avatar {
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: flex-end;
  padding: 24px;
  position: relative;
  overflow: hidden;
}
.instructor-avatar::before {
  content: attr(data-initial);
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-family: 'Oswald', sans-serif;
  font-size: 72px;
  font-weight: 700;
  color: rgba(255,0,0,0.18);
}
.instructor-info { padding: 20px; }
.instructor-name {
  font-family: 'Oswald', sans-serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 4px;
  letter-spacing: 0.05em;
}
.instructor-location { font-size: 12px; color: var(--red); text-transform: uppercase; letter-spacing: 0.15em; margin-bottom: 16px; }
.instructor-book {
  display: block;
  padding: 10px 0;
  text-align: center;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: all 0.2s;
}
.instructor-book:hover { background: var(--red); border-color: var(--red); color: var(--white); }
.instructor-card.hidden { display: none; }

/* ─── FAQ ACCORDION ─── */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border);
  overflow: hidden;
}
.faq-question {
  width: 100%;
  background: transparent;
  border: none;
  text-align: left;
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  gap: 16px;
  color: var(--white);
}
.faq-question-text {
  font-family: 'Oswald', sans-serif;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.faq-icon {
  width: 28px; height: 28px;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--red);
  font-size: 18px;
  font-weight: 300;
  transition: transform 0.3s, background 0.2s;
}
.faq-item.open .faq-icon { background: var(--red); color: var(--white); transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  padding: 0;
}
.faq-item.open .faq-answer { max-height: 300px; padding-bottom: 24px; }
.faq-answer-text { font-size: 15px; color: var(--gray); line-height: 1.8; text-transform: none; font-family: 'Inter', sans-serif; }

/* ─── DIGITAL FEATURES ─── */
.features-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
}
.feature-card {
  background: var(--bg-2);
  padding: 48px 40px;
  position: relative;
  overflow: hidden;
  border-left: 4px solid transparent;
  transition: border-color 0.25s, background 0.25s;
}
.feature-card:hover { border-left-color: var(--red); background: var(--bg-3); }
.feature-num {
  font-family: 'Oswald', sans-serif;
  font-size: 80px;
  font-weight: 700;
  color: rgba(255,0,0,0.06);
  position: absolute;
  top: 16px; right: 24px;
  line-height: 1;
}
.feature-icon { font-size: 32px; margin-bottom: 16px; }
.feature-title {
  font-family: 'Oswald', sans-serif;
  font-size: 26px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.feature-body { font-size: 14px; color: var(--gray); line-height: 1.8; text-transform: none; font-family: 'Inter', sans-serif; max-width: 380px; }

/* ─── CTA BAND ─── */
.cta-band {
  background: var(--bg-2);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 64px 24px;
  text-align: center;
}
.cta-band-title {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}
.cta-band-sub { font-size: 15px; color: var(--gray); margin-bottom: 32px; font-family: 'Inter', sans-serif; text-transform: none; }
.cta-band-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── COMMUNITY PROMO ─── */
.community-promo {
  padding: 96px 24px;
  text-align: center;
  background: var(--bg);
}
.community-title { font-size: clamp(40px, 5vw, 64px); font-weight: 700; color: var(--white); margin-bottom: 24px; }
.community-body { font-size: 16px; color: var(--gray); max-width: 640px; margin: 0 auto 36px; line-height: 1.8; font-family: 'Inter', sans-serif; text-transform: none; }

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .two-ways { grid-template-columns: 1fr; }
  .two-ways-card::before { width: 100%; height: 4px; top: 0; left: 0; }
  .two-ways-card:last-child::before { top: auto; bottom: 0; right: auto; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-utility .btn-nav-outline { display: none; }
  .instructor-grid { grid-template-columns: repeat(2, 1fr); }
  .method-grid { grid-template-columns: 1fr; }
  .toggle-panel.active { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .two-ways-card { padding: 48px 32px; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { border-right: 1px solid var(--border); border-bottom: none; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .carousel-slide { min-width: 100%; }
  .hero-btns { flex-direction: column; align-items: center; }
}

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --bg: #141414;
  --bg-2: #1a1a1a;
  --bg-3: #222222;
  --white: #FFFFFF;
  --gray: #999999;
  --gray-light: #cccccc;
  --border: #2a2a2a;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--white);
  font-family: 'Inter', Helvetica Neue, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5 {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

/* ─── TOP PROMO BAR ─── */
.promo-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.promo-bar a { text-decoration: underline; text-underline-offset: 3px; }
.promo-bar a:hover { opacity: 0.8; }

/* ─── NAVIGATION ─── */
.nav {
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}
.nav-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--white);
}
.nav-logo span { color: var(--red); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-light);
  transition: color 0.2s;
}
.nav-links a:hover,
.nav-links a.active { color: var(--red); }
.nav-utility {
  display: flex;
  align-items: center;
  gap: 12px;
}
.btn-nav {
  padding: 9px 20px;
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-block;
}
.btn-nav-outline {
  background: transparent;
  border: 1px solid var(--white);
  color: var(--white);
}
.btn-nav-outline:hover { background: var(--white); color: var(--bg); }
.btn-nav-red {
  background: var(--red);
  color: var(--white);
}
.btn-nav-red:hover { background: var(--red-dark); }

/* ─── BUTTONS ─── */
.btn {
  display: inline-block;
  padding: 16px 40px;
  font-family: 'Oswald', sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  border: none;
  transition: all 0.25s;
  text-align: center;
}
.btn-red { background: var(--red); color: var(--white); }
.btn-red:hover { background: var(--red-dark); transform: translateY(-1px); }
.btn-white { background: var(--white); color: var(--bg); }
.btn-white:hover { background: var(--gray-light); transform: translateY(-1px); }
.btn-outline-white {
  background: transparent;
  border: 2px solid var(--white);
  color: var(--white);
}
.btn-outline-white:hover { background: var(--white); color: var(--bg); }
.btn-outline-red {
  background: transparent;
  border: 2px solid var(--red);
  color: var(--red);
}
.btn-outline-red:hover { background: var(--red); color: var(--white); }
.btn-lg { padding: 20px 56px; font-size: 17px; }

/* ─── SECTIONS ─── */
.section { padding: 96px 24px; }
.section-sm { padding: 64px 24px; }
.container { max-width: 1200px; margin: 0 auto; }
.container-wide { max-width: 1400px; margin: 0 auto; }

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: var(--bg);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0000 0%, #141414 40%, #0a0a0a 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 60%, rgba(255,0,0,0.15) 0%, transparent 65%);
}
.hero-content { position: relative; z-index: 2; max-width: 900px; padding: 48px 24px; }
.hero-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
}
.hero-title {
  font-size: clamp(52px, 9vw, 100px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 24px;
  text-shadow: 0 4px 40px rgba(0,0,0,0.6);
}
.hero-title span { color: var(--red); }
.hero-subtitle {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--gray-light);
  max-width: 580px;
  margin: 0 auto 40px;
  line-height: 1.65;
  font-weight: 300;
  text-transform: none;
  font-family: 'Inter', sans-serif;
}
.hero-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── RED DIVIDER ─── */
.red-line { width: 60px; height: 4px; background: var(--red); margin-bottom: 24px; }
.red-line-center { margin-left: auto; margin-right: auto; }

/* ─── SECTION HEADING ─── */
.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.25em;
  color: var(--red);
  text-transform: uppercase;
  margin-bottom: 12px;
}
.section-title {
  font-size: clamp(36px, 5vw, 60px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 20px;
}
.section-body {
  font-size: 16px;
  color: var(--gray);
  max-width: 600px;
  line-height: 1.8;
  font-family: 'Inter', sans-serif;
  text-transform: none;
}

/* ─── TWO WAYS SECTION ─── */
.two-ways { display: grid; grid-template-columns: 1fr 1fr; }
.two-ways-card {
  padding: 80px 60px;
  position: relative;
  overflow: hidden;
}
.two-ways-card:first-child { background: var(--bg-2); }
.two-ways-card:last-child { background: #0d0d0d; }
.two-ways-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 4px; height: 100%;
  background: var(--red);
}
.two-ways-card:last-child::before { left: auto; right: 0; }
.two-ways-num {
  font-family: 'Oswald', sans-serif;
  font-size: 100px;
  font-weight: 700;
  color: rgba(255,0,0,0.08);
  position: absolute;
  top: 20px; right: 24px;
  line-height: 1;
}
.two-ways-icon { font-size: 40px; margin-bottom: 20px; }
.two-ways-title { font-size: 36px; font-weight: 700; color: var(--white); margin-bottom: 16px; }
.two-ways-body { font-size: 15px; color: var(--gray); line-height: 1.8; font-family: 'Inter', sans-serif; text-transform: none; max-width: 400px; }

/* ─── STUDIO EXPERIENCE ─── */
.studio-exp {
  background: linear-gradient(135deg, #1a0000 0%, #0d0000 100%);
  padding: 100px 24px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.studio-exp::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(255,0,0,0.2) 0%, transparent 70%);
}
.studio-exp > * { position: relative; z-index: 1; }

/* ─── FREE TRIAL ─── */
.free-trial {
  background: var(--red);
  padding: 96px 24px;
  text-align: center;
}
.free-trial-title {
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 36px;
}

/* ─── CAROUSEL ─── */
.carousel-section { background: var(--bg-2); padding: 80px 0; }
.carousel-wrap { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.carousel-slide {
  min-width: 33.333%;
  padding: 0 8px;
  flex-shrink: 0;
}
.carousel-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: 2px;
}
.carousel-placeholder {
  width: 100%;
  aspect-ratio: 4/3;
  background: var(--bg-3);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 2px;
  position: relative;
  overflow: hidden;
}
.carousel-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0000, #141414);
}
.carousel-placeholder-text {
  position: relative;
  font-family: 'Oswald', sans-serif;
  font-size: 24px;
  font-weight: 700;
  color: rgba(255,0,0,0.4);
  letter-spacing: 0.1em;
  text-align: center;
}
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
  padding: 0 24px;
}
.carousel-btn {
  width: 48px; height: 48px;
  background: transparent;
  border: 2px solid var(--border);
  color: var(--white);
  font-size: 20px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.carousel-btn:hover { border-color: var(--red); color: var(--red); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px;
  background: var(--border);
  border-radius: 50%;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* ─── NEWSLETTER ─── */
.newsletter {
  background: var(--bg-2);
  padding: 80px 24px;
  text-align: center;
  border-top: 1px solid var(--border);
}
.newsletter-form {
  display: flex;
  max-width: 480px;
  margin: 28px auto 0;
  gap: 0;
}
.newsletter-input {
  flex: 1;
  padding: 16px 20px;
  background: var(--bg-3);
  border: 1px solid var(--border);
  border-right: none;
  color: var(--white);
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-input:focus { border-color: var(--red); }
.newsletter-input::placeholder { color: var(--gray); }
.newsletter-input.error { border-color: #ff4444; }
.newsletter-btn {
  padding: 16px 28px;
  background: var(--red);
  color: var(--white);
  border: none;
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.2s;
}
.newsletter-btn:hover { background: var(--red-dark); }
.newsletter-msg { margin-top: 12px; font-size: 13px; min-height: 20px; }
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: #ff4444; }

/* ─── FOOTER ─── */
.footer {
  background: #0d0d0d;
  border-top: 1px solid var(--border);
  padding: 64px 24px 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  max-width: 1200px;
  margin: 0 auto 48px;
}
.footer-brand-logo {
  font-family: 'Oswald', sans-serif;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.footer-brand-logo span { color: var(--red); }
.footer-tagline { font-size: 13px; color: var(--gray); line-height: 1.7; max-width: 260px; text-transform: none; }
.footer-col-title {
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 10px; }
.footer-links a {
  font-size: 13px;
  color: var(--gray);
  transition: color 0.2s;
  text-transform: none;
}
.footer-links a:hover { color: var(--red); }
.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 32px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-copy { font-size: 12px; color: var(--gray); text-transform: none; }
.country-select {
  background: var(--bg-3);
  border: 1px solid var(--border);
  color: var(--gray-light);
  padding: 8px 16px;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  cursor: pointer;
  outline: none;
}
.country-select:focus { border-color: var(--red); }

/* ─── PAGE HERO (interior) ─── */
.page-hero {
  background: linear-gradient(135deg, #1a0000 0%, #141414 50%, #0a0a0a 100%);
  padding: 100px 24px 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 100%, rgba(255,0,0,0.12) 0%, transparent 60%);
}
.page-hero > * { position: relative; z-index: 1; }
.page-hero-title { font-size: clamp(48px, 7vw, 84px); font-weight: 700; color: var(--white); }
.page-hero-sub { font-size: 16px; color: var(--gray); margin-top: 16px; max-width: 540px; margin-left: auto; margin-right: auto; font-family: 'Inter', sans-serif; text-transform: none; line-height: 1.7; }

/* ─── METHOD OVERVIEW ─── */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.method-img-placeholder {
  aspect-ratio: 5/4;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.method-img-placeholder::before {
  content: 'REDROOM';
  font-family: 'Oswald', sans-serif;
  font-size: 48px;
  font-weight: 700;
  color: rgba(255,0,0,0.15);
  letter-spacing: 0.15em;
}

/* ─── SCHEDULE TABLE ─── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 40px;
}
.schedule-table th {
  background: var(--red);
  color: var(--white);
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 16px 24px;
  text-align: left;
}
.schedule-table td {
  padding: 18px 24px;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--gray-light);
}
.schedule-table tr:hover td { background: var(--bg-2); color: var(--white); }
.schedule-table .day-cell {
  font-family: 'Oswald', sans-serif;
  font-weight: 600;
  font-size: 16px;
  color: var(--white);
  letter-spacing: 0.06em;
}

/* ─── TOGGLE ─── */
.toggle-wrap { margin: 48px 0; }
.toggle-tabs {
  display: flex;
  border: 1px solid var(--border);
  max-width: 400px;
  margin: 0 auto 48px;
}
.toggle-tab {
  flex: 1;
  padding: 16px 24px;
  background: transparent;
  border: none;
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.25s;
  position: relative;
}
.toggle-tab.active {
  background: var(--red);
  color: var(--white);
}
.toggle-tab:not(.active):hover { color: var(--white); background: rgba(255,255,255,0.05); }
.toggle-panel { display: none; }
.toggle-panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  animation: fadeIn 0.35s ease;
}
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.toggle-panel-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.toggle-panel-img-label {
  font-family: 'Oswald', sans-serif;
  font-size: 36px;
  font-weight: 700;
  color: rgba(255,0,0,0.25);
  letter-spacing: 0.12em;
}
.toggle-panel-content .section-title { font-size: 42px; }

/* ─── INSTRUCTOR GRID ─── */
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 22px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s;
}
.filter-btn:hover { border-color: var(--white); color: var(--white); }
.filter-btn.active { background: var(--red); border-color: var(--red); color: var(--white); }
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg-2);
  border: 1px solid var(--border);
  padding: 0;
  overflow: hidden;
  transition: transform 0.25s, border-color 0.25s;
}
.instructor-card:hover { transform: translateY(-4px); border-color: var(--red); }
.instructor-avatar {
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, #1a0000, #0d0000);
  display: flex;
  align-items: flex-end;
  padding: 24px;
  position: relative;
  overflow: hidden;
}
.instructor-avatar::before {
  content: attr(data-initial);
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-family: 'Oswald', sans-serif;
  font-size: 72px;
  font-weight: 700;
  color: rgba(255,0,0,0.18);
}
.instructor-info { padding: 20px; }
.instructor-name {
  font-family: 'Oswald', sans-serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 4px;
  letter-spacing: 0.05em;
}
.instructor-location { font-size: 12px; color: var(--red); text-transform: uppercase; letter-spacing: 0.15em; margin-bottom: 16px; }
.instructor-book {
  display: block;
  padding: 10px 0;
  text-align: center;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: all 0.2s;
}
.instructor-book:hover { background: var(--red); border-color: var(--red); color: var(--white); }
.instructor-card.hidden { display: none; }

/* ─── FAQ ACCORDION ─── */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border);
  overflow: hidden;
}
.faq-question {
  width: 100%;
  background: transparent;
  border: none;
  text-align: left;
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  gap: 16px;
  color: var(--white);
}
.faq-question-text {
  font-family: 'Oswald', sans-serif;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.faq-icon {
  width: 28px; height: 28px;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--red);
  font-size: 18px;
  font-weight: 300;
  transition: transform 0.3s, background 0.2s;
}
.faq-item.open .faq-icon { background: var(--red); color: var(--white); transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
  padding: 0;
}
.faq-item.open .faq-answer { max-height: 300px; padding-bottom: 24px; }
.faq-answer-text { font-size: 15px; color: var(--gray); line-height: 1.8; text-transform: none; font-family: 'Inter', sans-serif; }

/* ─── DIGITAL FEATURES ─── */
.features-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
}
.feature-card {
  background: var(--bg-2);
  padding: 48px 40px;
  position: relative;
  overflow: hidden;
  border-left: 4px solid transparent;
  transition: border-color 0.25s, background 0.25s;
}
.feature-card:hover { border-left-color: var(--red); background: var(--bg-3); }
.feature-num {
  font-family: 'Oswald', sans-serif;
  font-size: 80px;
  font-weight: 700;
  color: rgba(255,0,0,0.06);
  position: absolute;
  top: 16px; right: 24px;
  line-height: 1;
}
.feature-icon { font-size: 32px; margin-bottom: 16px; }
.feature-title {
  font-family: 'Oswald', sans-serif;
  font-size: 26px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.feature-body { font-size: 14px; color: var(--gray); line-height: 1.8; text-transform: none; font-family: 'Inter', sans-serif; max-width: 380px; }

/* ─── CTA BAND ─── */
.cta-band {
  background: var(--bg-2);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 64px 24px;
  text-align: center;
}
.cta-band-title {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}
.cta-band-sub { font-size: 15px; color: var(--gray); margin-bottom: 32px; font-family: 'Inter', sans-serif; text-transform: none; }
.cta-band-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── COMMUNITY PROMO ─── */
.community-promo {
  padding: 96px 24px;
  text-align: center;
  background: var(--bg);
}
.community-title { font-size: clamp(40px, 5vw, 64px); font-weight: 700; color: var(--white); margin-bottom: 24px; }
.community-body { font-size: 16px; color: var(--gray); max-width: 640px; margin: 0 auto 36px; line-height: 1.8; font-family: 'Inter', sans-serif; text-transform: none; }

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .instructor-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .two-ways { grid-template-columns: 1fr; }
  .two-ways-card::before { width: 100%; height: 4px; top: 0; left: 0; }
  .two-ways-card:last-child::before { top: auto; bottom: 0; right: auto; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-utility .btn-nav-outline { display: none; }
  .instructor-grid { grid-template-columns: repeat(2, 1fr); }
  .method-grid { grid-template-columns: 1fr; }
  .toggle-panel.active { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .two-ways-card { padding: 48px 32px; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { border-right: 1px solid var(--border); border-bottom: none; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .carousel-slide { min-width: 100%; }
  .hero-btns { flex-direction: column; align-items: center; }
}
